// StackSwitcher — Gtk.StackSwitcher
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles stackswitcher with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface StackSwitcherProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Stack, from Gtk.StackSwitcher */
  stack?: ReactNode
}

export function StackSwitcher({ className, children }: StackSwitcherProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
